//! The notebook screen (P5), client side: the skill tree (buy with a click) and the research
//! diary (evidence and voluntary hints). It draws what the server last sent
//! (`mistbrn:progress`) and asks for changes with `mistbrn:control` requests; the server decides.
//!
//! The atlas `mistbrn:gui/progress` is generated by `tools/gen-progress.py` (Claude ⇄ Codex);
//! its regions are the contract below.
use crate::hud::{tr, tr_args};
use allomancy_core::{
    CATALOG, ControlRequest, NodeDef, NodeEffect, NodeStatus, Pair, Pool, Progress, Requirement,
    node_def, node_status, research_def, research_ready, xp_to_next_point,
};
use mod_api::{ClientHost, DrawContext};

const SHEET: &str = "mistbrn:gui/progress";
const NODE_LOCKED: [f32; 4] = [0.0, 0.0, 22.0, 22.0];
const NODE_AVAILABLE: [f32; 4] = [22.0, 0.0, 22.0, 22.0];
const NODE_OWNED: [f32; 4] = [44.0, 0.0, 22.0, 22.0];
const NODE_HOVER: [f32; 4] = [66.0, 0.0, 22.0, 22.0];
const ICON_Y: f32 = 24.0;
const ICON_RESEARCH: [f32; 4] = [80.0, 24.0, 16.0, 16.0];
const ICON_HINT: [f32; 4] = [96.0, 24.0, 16.0, 16.0];
const PIP_EMPTY: [f32; 4] = [112.0, 24.0, 4.0, 4.0];
const PIP_FULL: [f32; 4] = [116.0, 24.0, 4.0, 4.0];
const TAB: [f32; 4] = [0.0, 40.0, 48.0, 14.0];
const TAB_SELECTED: [f32; 4] = [48.0, 40.0, 48.0, 14.0];
const CHECK_FOUND: [f32; 4] = [96.0, 40.0, 9.0, 9.0];
const CHECK_MISSING: [f32; 4] = [105.0, 40.0, 9.0, 9.0];
const POINT: [f32; 4] = [114.0, 40.0, 7.0, 7.0];

const PANEL_W: f32 = 236.0;
const PANEL_H: f32 = 172.0;
const BODY: u32 = 0xE018_1A20;
const OUTLINE: u32 = 0xFF0A_0B0E;
const BEVEL: u32 = 0xFF45_4A50;
const TEXT: u32 = 0xFFE0_E0E0;
const DIM: u32 = 0xFF90_9090;
const BRASS: u32 = 0xFFF0_D48A;
const READY: u32 = 0xFFB8_E0A0;
const LOCKED_TINT: u32 = 0xFF70_7070;
const BUTTON: u32 = 0xFF2E_3238;
const BUTTON_HOVER: u32 = 0xFF45_4A50;
const LINE: f32 = 10.0;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Tab {
    Tree,
    Diary,
}

/// Something under the pointer that a click acts on.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Target {
    Tab(Tab),
    Node(u16),
    RevealHint,
    /// Show revealed hint number n (1-based).
    HintPage(u8),
}

/// Where the notebook's nodes sit, relative to the panel: the iron and steel row, then the
/// general row. Catalog codes; a code missing from the catalog is not drawn.
const LAYOUT: [(u16, f32, f32); 5] = [
    (allomancy_core::NODE_REACH, 24.0, 34.0),
    (allomancy_core::NODE_ACCEL, 84.0, 34.0),
    (allomancy_core::NODE_COIN_JUMP, 144.0, 34.0),
    (allomancy_core::NODE_ECONOMY, 24.0, 84.0),
    (allomancy_core::NODE_CAPACITY, 84.0, 84.0),
];
const HINT_BUTTON: [f32; 4] = [PANEL_W - 104.0, 84.0, 96.0, 12.0];
/// The first hint page button (12×12), the others follow every 14 px.
const HINT_PAGE: [f32; 2] = [62.0, 84.0];

fn hint_page_rect(o: [f32; 2], index: u8) -> [f32; 4] {
    let x = o[0] + HINT_PAGE[0] + 14.0 * f32::from(index - 1);
    [x, o[1] + HINT_PAGE[1], 12.0, 12.0]
}

fn origin(size: [f32; 2]) -> [f32; 2] {
    [
        ((size[0] - PANEL_W) / 2.0).floor(),
        // Room for the tabs above; the panel's bottom stays clear of the XP bar and hotbar.
        ((size[1] - PANEL_H) / 2.0).floor() - 2.0,
    ]
}

fn inside(point: [f32; 2], rect: [f32; 4]) -> bool {
    point[0] >= rect[0]
        && point[1] >= rect[1]
        && point[0] < rect[0] + rect[2]
        && point[1] < rect[1] + rect[3]
}

fn tab_rect(o: [f32; 2], tab: Tab) -> [f32; 4] {
    let x = match tab {
        Tab::Tree => 6.0,
        Tab::Diary => 58.0,
    };
    [o[0] + x, o[1] - TAB[3] + 1.0, TAB[2], TAB[3]]
}

/// The centre of a node on the screen (scenarios click there).
pub(crate) fn node_centre(size: [f32; 2], code: u16) -> Option<[f32; 2]> {
    let o = origin(size);
    LAYOUT
        .iter()
        .find(|(c, ..)| *c == code)
        .map(|&(_, x, y)| [o[0] + x + 11.0, o[1] + y + 11.0])
}

/// The centre of the diary's reveal button on the screen (scenarios click there).
pub(crate) fn hint_button_centre(size: [f32; 2]) -> Option<[f32; 2]> {
    let o = origin(size);
    let [x, y, w, h] = HINT_BUTTON;
    Some([o[0] + x + w / 2.0, o[1] + y + h / 2.0])
}

/// The centre of a tab (scenarios click there).
pub(crate) fn tab_centre(size: [f32; 2], tab: Tab) -> [f32; 2] {
    let [x, y, w, h] = tab_rect(origin(size), tab);
    [x + w / 2.0, y + h / 2.0]
}

/// What the pointer is over on `tab`.
pub(crate) fn target(size: [f32; 2], pointer: [f32; 2], tab: Tab) -> Option<Target> {
    let o = origin(size);
    for candidate in [Tab::Tree, Tab::Diary] {
        if inside(pointer, tab_rect(o, candidate)) {
            return Some(Target::Tab(candidate));
        }
    }
    match tab {
        Tab::Tree => LAYOUT.iter().find_map(|&(code, x, y)| {
            inside(pointer, [o[0] + x, o[1] + y, 22.0, 22.0]).then_some(Target::Node(code))
        }),
        Tab::Diary => {
            let [x, y, w, h] = HINT_BUTTON;
            if inside(pointer, [o[0] + x, o[1] + y, w, h]) {
                return Some(Target::RevealHint);
            }
            (1..=3u8)
                .find(|&i| inside(pointer, hint_page_rect(o, i)))
                .map(Target::HintPage)
        }
    }
}

/// The request a click on `target` sends, if any (a node that can be bought, the next hint).
pub(crate) fn request(
    target: Target,
    progress: &Progress,
    unlocked: impl Fn(Pair) -> bool,
) -> Option<ControlRequest> {
    match target {
        Target::Tab(_) | Target::HintPage(_) => None,
        Target::Node(code) => {
            let def = node_def(code, &CATALOG)?;
            (node_status(progress, def, unlocked, &CATALOG) == NodeStatus::Available).then(|| {
                ControlRequest::Purchase {
                    code: u8::try_from(code).unwrap_or(0),
                    rank: progress.rank(code) + 1,
                }
            })
        }
        Target::RevealHint => {
            let def = CATALOG.research.first()?;
            let shown = progress.research(def.code).hints;
            (shown < def.hints).then(|| ControlRequest::RevealHint {
                research: u8::try_from(def.code).unwrap_or(0),
                index: shown + 1,
            })
        }
    }
}

fn sprite(draw: &mut dyn DrawContext, src: [f32; 4], at: [f32; 2], tint: Option<u32>) -> bool {
    draw.sprite(SHEET, src, [at[0], at[1], src[2], src[3]], tint)
}

fn icon(code: u16) -> [f32; 4] {
    let column = CATALOG
        .nodes
        .iter()
        .position(|def| def.code == code)
        .unwrap_or(0) as f32;
    [16.0 * column, ICON_Y, 16.0, 16.0]
}

/// The value an effect shows to a player: blocks or percent.
fn shown_value(effect: NodeEffect, value: u16) -> String {
    match effect {
        NodeEffect::ReductionMilli | NodeEffect::CapacityBonusMilli => {
            let tenths = value % 10;
            if tenths == 0 {
                format!("{}", value / 10)
            } else {
                format!("{}.{tenths}", value / 10)
            }
        }
        _ => value.to_string(),
    }
}

fn node_name(host: &dyn ClientHost, def: &NodeDef) -> String {
    tr(host, &format!("node.mistbrn.{}", def.key))
}

fn wrap(draw: &dyn DrawContext, text: &str, width: f32) -> Vec<String> {
    let mut lines = Vec::new();
    let mut line = String::new();
    for word in text.split_whitespace() {
        let candidate = if line.is_empty() {
            word.to_string()
        } else {
            format!("{line} {word}")
        };
        if !line.is_empty() && draw.text_width(&candidate) > width {
            lines.push(std::mem::replace(&mut line, word.to_string()));
        } else {
            line = candidate;
        }
    }
    if !line.is_empty() {
        lines.push(line);
    }
    lines
}

/// Draws the notebook over the world. `unlocked` answers whether a pair is unlocked (from the
/// HUD snapshot); `progress` is `None` until the server's first snapshot arrives.
pub(crate) fn draw(
    host: &dyn ClientHost,
    draw: &mut dyn DrawContext,
    tab: Tab,
    progress: Option<&Progress>,
    unlocked: &dyn Fn(Pair) -> bool,
    pointer: [f32; 2],
    hint_page: Option<u8>,
) {
    let size = draw.size();
    let o = origin(size);
    draw.fill([0.0, 0.0, size[0], size[1]], 0x6000_0000);
    for candidate in [Tab::Tree, Tab::Diary] {
        let rect = tab_rect(o, candidate);
        let src = if candidate == tab { TAB_SELECTED } else { TAB };
        if !sprite(draw, src, [rect[0], rect[1]], None) {
            draw.fill(rect, if candidate == tab { BEVEL } else { BUTTON });
        }
        let key = match candidate {
            Tab::Tree => "notebook.mistbrn.tab.tree",
            Tab::Diary => "notebook.mistbrn.tab.diary",
        };
        let label = tr(host, key);
        let color = if candidate == tab { BRASS } else { DIM };
        let x = rect[0] + (rect[2] - draw.text_width(&label)) / 2.0;
        draw.text(&label, [x, rect[1] + 3.0], color, true);
    }
    draw.fill([o[0], o[1], PANEL_W, PANEL_H], OUTLINE);
    draw.fill(
        [o[0] + 1.0, o[1] + 1.0, PANEL_W - 2.0, PANEL_H - 2.0],
        BEVEL,
    );
    draw.fill([o[0] + 2.0, o[1] + 2.0, PANEL_W - 4.0, PANEL_H - 4.0], BODY);
    let Some(progress) = progress else {
        let wait = tr(host, "notebook.mistbrn.waiting");
        draw.text(&wait, [o[0] + 8.0, o[1] + 8.0], DIM, true);
        return;
    };
    let hovered = target(size, pointer, tab);
    match tab {
        Tab::Tree => draw_tree(host, draw, o, progress, unlocked, hovered),
        Tab::Diary => draw_diary(host, draw, o, progress, hovered, hint_page),
    }
}

/// A points count, right-aligned at `at`, with its gem before it.
fn draw_points(draw: &mut dyn DrawContext, at: [f32; 2], text: &str) {
    let x = at[0] - draw.text_width(text);
    draw.text(text, [x, at[1]], TEXT, true);
    if !sprite(draw, POINT, [x - POINT[2] - 2.0, at[1]], None) {
        draw.fill([x - 7.0, at[1] + 1.0, 5.0, 5.0], BRASS);
    }
}

fn draw_tree(
    host: &dyn ClientHost,
    draw: &mut dyn DrawContext,
    o: [f32; 2],
    progress: &Progress,
    unlocked: &dyn Fn(Pair) -> bool,
    hovered: Option<Target>,
) {
    let xp = progress.pair_xp(Pair::IronSteel);
    let title = tr(host, "hud.mistbrn.pair.iron_steel");
    draw.text(&title, [o[0] + 8.0, o[1] + 7.0], BRASS, true);
    let points = progress
        .available(Pool::Pair(Pair::IronSteel), &CATALOG)
        .to_string();
    draw_points(draw, [o[0] + PANEL_W - 8.0, o[1] + 7.0], &points);
    let next = tr_args(
        host,
        "notebook.mistbrn.xp",
        &[xp.to_string(), xp_to_next_point(xp, &CATALOG).to_string()],
    );
    draw.text(&next, [o[0] + 8.0, o[1] + 19.0], DIM, true);

    let general = tr(host, "notebook.mistbrn.general");
    draw.text(&general, [o[0] + 8.0, o[1] + 70.0], BRASS, true);
    let knowledge = progress.available(Pool::Knowledge, &CATALOG).to_string();
    draw_points(draw, [o[0] + PANEL_W - 8.0, o[1] + 70.0], &knowledge);

    for &(code, x, y) in &LAYOUT {
        let Some(def) = node_def(code, &CATALOG) else {
            continue;
        };
        let status = node_status(progress, def, unlocked, &CATALOG);
        let at = [o[0] + x, o[1] + y];
        let frame = if hovered == Some(Target::Node(code)) {
            NODE_HOVER
        } else {
            match status {
                NodeStatus::Locked | NodeStatus::TooExpensive => NODE_LOCKED,
                NodeStatus::Available => NODE_AVAILABLE,
                NodeStatus::Owned => NODE_OWNED,
            }
        };
        if !sprite(draw, frame, at, None) {
            draw.fill([at[0], at[1], 22.0, 22.0], BEVEL);
        }
        let tint = (status == NodeStatus::Locked).then_some(LOCKED_TINT);
        sprite(draw, icon(code), [at[0] + 3.0, at[1] + 3.0], tint);
        let owned = usize::from(progress.rank(code));
        let start = at[0] + 11.0 - (def.ranks.len() as f32 * 6.0 - 2.0) / 2.0;
        for i in 0..def.ranks.len() {
            let src = if i < owned { PIP_FULL } else { PIP_EMPTY };
            sprite(draw, src, [start + 6.0 * i as f32, at[1] + 25.0], None);
        }
    }

    // The hovered node, described at the bottom; otherwise how the tree works.
    let Some(Target::Node(code)) = hovered else {
        let help = tr(host, "notebook.mistbrn.help.tree");
        for (i, line) in wrap(draw, &help, PANEL_W - 16.0).iter().enumerate() {
            draw.text(
                line,
                [o[0] + 8.0, o[1] + 134.0 + LINE * i as f32],
                DIM,
                true,
            );
        }
        return;
    };
    let Some(def) = node_def(code, &CATALOG) else {
        return;
    };
    let owned = progress.rank(code);
    let status = node_status(progress, def, unlocked, &CATALOG);
    let head = format!("{} {}/{}", node_name(host, def), owned, def.ranks.len());
    draw.text(&head, [o[0] + 8.0, o[1] + 130.0], BRASS, true);
    let detail = match def.ranks.get(usize::from(owned)) {
        None => tr(host, "notebook.mistbrn.status.owned"),
        Some(rank) => {
            let effect = tr_args(
                host,
                &format!("node.mistbrn.{}.effect", def.key),
                &[shown_value(def.effect, rank.value)],
            );
            let cost = tr_args(host, "notebook.mistbrn.cost", &[rank.cost.to_string()]);
            format!("{effect} · {cost}")
        }
    };
    draw.text(&detail, [o[0] + 8.0, o[1] + 141.0], TEXT, true);
    let note = match status {
        NodeStatus::Available => tr(host, "notebook.mistbrn.status.available"),
        NodeStatus::TooExpensive => tr(host, "notebook.mistbrn.status.expensive"),
        NodeStatus::Owned => String::new(),
        NodeStatus::Locked => requirement_text(host, def, progress, unlocked),
    };
    let color = if status == NodeStatus::Available {
        READY
    } else {
        DIM
    };
    draw.text(&note, [o[0] + 8.0, o[1] + 152.0], color, true);
}

fn requirement_text(
    host: &dyn ClientHost,
    def: &NodeDef,
    progress: &Progress,
    unlocked: &dyn Fn(Pair) -> bool,
) -> String {
    if let Pool::Pair(pair) = def.pool
        && !unlocked(pair)
    {
        return tr(host, "notebook.mistbrn.requires.pair");
    }
    for requirement in def.requires {
        match *requirement {
            Requirement::Node { code, rank } if progress.rank(code) < rank => {
                let name =
                    node_def(code, &CATALOG).map_or_else(String::new, |d| node_name(host, d));
                return tr_args(
                    host,
                    "notebook.mistbrn.requires.node",
                    &[name, rank.to_string()],
                );
            }
            Requirement::Discovery { code } if !progress.discovered(code) => {
                let name = research_def(code, &CATALOG).map_or_else(String::new, |d| {
                    tr(host, &format!("research.mistbrn.{}", d.key))
                });
                return tr_args(host, "notebook.mistbrn.requires.discovery", &[name]);
            }
            _ => {}
        }
    }
    String::new()
}

fn draw_diary(
    host: &dyn ClientHost,
    draw: &mut dyn DrawContext,
    o: [f32; 2],
    progress: &Progress,
    hovered: Option<Target>,
    hint_page: Option<u8>,
) {
    let Some(def) = CATALOG.research.first() else {
        return;
    };
    let entry = progress.research(def.code);
    sprite(draw, ICON_RESEARCH, [o[0] + 6.0, o[1] + 4.0], None);
    let name = tr(host, &format!("research.mistbrn.{}", def.key));
    draw.text(&name, [o[0] + 26.0, o[1] + 8.0], BRASS, true);
    let (status, color) = if entry.concluded {
        ("notebook.mistbrn.research.discovered", BRASS)
    } else if research_ready(progress, def) {
        ("notebook.mistbrn.research.ready", READY)
    } else {
        ("notebook.mistbrn.research.open", DIM)
    };
    let status = tr(host, status);
    let x = o[0] + PANEL_W - 8.0 - draw.text_width(&status);
    draw.text(&status, [x, o[1] + 8.0], color, true);
    let found = entry.evidence.count_ones().min(u32::from(def.needed));
    let count = tr_args(
        host,
        "notebook.mistbrn.evidence",
        &[found.to_string(), def.needed.to_string()],
    );
    draw.text(&count, [o[0] + 8.0, o[1] + 24.0], TEXT, true);
    // Each piece of evidence: what was seen, or a blank until it is (discovery stays free).
    let mut y = o[1] + 36.0;
    for bit in [1u8, 2, 4] {
        if def.evidence & bit == 0 {
            continue;
        }
        let seen = entry.evidence & bit != 0;
        let check = if seen { CHECK_FOUND } else { CHECK_MISSING };
        sprite(draw, check, [o[0] + 8.0, y], None);
        let text = if seen {
            tr(
                host,
                &format!("research.mistbrn.{}.evidence.{bit}", def.key),
            )
        } else {
            tr(host, "notebook.mistbrn.evidence.unknown")
        };
        let color = if seen { TEXT } else { DIM };
        draw.text(&text, [o[0] + 21.0, y + 1.0], color, true);
        y += 12.0;
    }

    sprite(draw, ICON_HINT, [o[0] + 6.0, o[1] + 82.0], None);
    let hints = tr(host, "notebook.mistbrn.hints");
    draw.text(&hints, [o[0] + 26.0, o[1] + 86.0], BRASS, true);
    if entry.hints < def.hints {
        let [x, by, w, h] = HINT_BUTTON;
        let rect = [o[0] + x, o[1] + by, w, h];
        let fill = if hovered == Some(Target::RevealHint) {
            BUTTON_HOVER
        } else {
            BUTTON
        };
        draw.fill(rect, OUTLINE);
        draw.fill([rect[0] + 1.0, rect[1] + 1.0, w - 2.0, h - 2.0], fill);
        let label = tr_args(
            host,
            "notebook.mistbrn.reveal",
            &[(entry.hints + 1).to_string(), def.hints.to_string()],
        );
        let lx = rect[0] + (w - draw.text_width(&label)) / 2.0;
        draw.text(&label, [lx, rect[1] + 2.0], TEXT, true);
    }
    let bottom = o[1] + PANEL_H - 12.0;
    let mut y = o[1] + 102.0;
    if entry.hints == 0 {
        let none = tr(host, "notebook.mistbrn.hints.none");
        for line in wrap(draw, &none, PANEL_W - 16.0) {
            draw.text(&line, [o[0] + 8.0, y], DIM, true);
            y += LINE;
        }
    }
    // One hint at a time (the newest unless another page is chosen): long hints never push
    // a just-revealed one out of the panel.
    for index in 1..=entry.hints {
        let rect = hint_page_rect(o, index);
        let shown = hint_page.unwrap_or(entry.hints).min(entry.hints) == index;
        let fill = if shown || hovered == Some(Target::HintPage(index)) {
            BUTTON_HOVER
        } else {
            BUTTON
        };
        draw.fill(rect, OUTLINE);
        draw.fill([rect[0] + 1.0, rect[1] + 1.0, 10.0, 10.0], fill);
        let label = index.to_string();
        let lx = rect[0] + (12.0 - draw.text_width(&label)) / 2.0;
        draw.text(
            &label,
            [lx, rect[1] + 2.0],
            if shown { BRASS } else { TEXT },
            true,
        );
    }
    if entry.hints > 0 {
        let index = hint_page.unwrap_or(entry.hints).clamp(1, entry.hints);
        let hint = tr(host, &format!("research.mistbrn.{}.hint.{index}", def.key));
        for line in wrap(draw, &hint, PANEL_W - 16.0) {
            if y >= bottom {
                break;
            }
            draw.text(&line, [o[0] + 8.0, y], TEXT, true);
            y += LINE;
        }
    }
    if research_ready(progress, def) {
        let how = tr(host, "notebook.mistbrn.research.how");
        draw.text(&how, [o[0] + 8.0, bottom], READY, true);
    }
}
